import Cassowary

let x = Variable("shared x")
let shared = Constraint(Expression(x).minus(Expression(constant: 25)), .equal)
let a = Solver(), b = Solver()
try a.addConstraint(shared)
try b.addConstraint(shared)
precondition(a.hasConstraint(shared) && b.hasConstraint(shared), "adding to second solver clobbered first handle")
a.updateVariables(); b.updateVariables()
precondition(a.value(of: x) == 25 && b.value(of: x) == 25)
try b.removeConstraint(shared)
precondition(a.hasConstraint(shared) && !b.hasConstraint(shared), "removing from one solver affected another")
try a.updateConstraintConstant(shared, constant: -40)
a.updateVariables()
precondition(a.value(of: x) == 40)
try b.addConstraint(shared)
b.reset()
precondition(a.hasConstraint(shared) && !b.hasConstraint(shared), "reset affected other solver")
try a.removeConstraint(shared)
precondition(!a.hasConstraint(shared))
print("PASS: shared constraint handles remain independent across add/remove/update/reset")
